-- ============ KORENSLANG ============
WITH a AS (
  INSERT INTO public.academies (diersoort_naam, diersoort_naam_fr, diersoort_naam_en, slug, badge_icon, vragen_per_test, slaag_grens, beschrijving, beschrijving_fr, beschrijving_en, categorie, prioriteit)
  VALUES ('Korenslang','Serpent des blés','Corn Snake','korenslang','korenslang',12,9,'De korenslang is een rustige, veelgehouden slang die een correct temperatuurverloop en verzorging nodig heeft.','Le serpent des blés est un serpent calme et populaire qui a besoin d''un bon gradient de température et de soins adaptés.','The corn snake is a calm, popular pet snake that needs a proper temperature gradient and correct care.','exoten',20)
  RETURNING id
)
INSERT INTO public.academy_vragen (academy_id, module, vraag_type, vraag_tekst, vraag_tekst_fr, vraag_tekst_en, opties, opties_fr, opties_en, correcte_optie_index, wist_je_dat, wist_je_dat_fr, wist_je_dat_en)
SELECT a.id, v.module, v.vraag_type, v.nl, v.fr, v.en, v.onl, v.ofr, v.oen, v.ci, v.wnl, v.wfr, v.wen
FROM a, (VALUES
(1,'tekst','Wat is een goede warme kant-temperatuur (basking spot) voor een korenslang?','Quelle est une bonne température du côté chaud (zone de chauffe) pour un serpent des blés ?','What is a good warm-side (basking) temperature for a corn snake?','["Ongeveer 29-32°C","Ongeveer 40°C","Ongeveer 18°C","Kamertemperatuur volstaat"]'::jsonb,'["Environ 29-32°C","Environ 40°C","Environ 18°C","La température ambiante suffit"]'::jsonb,'["About 29-32°C","About 40°C","About 18°C","Room temperature is enough"]'::jsonb,0,'Een thermisch gradiënt laat de slang zelf de juiste temperatuur kiezen door te bewegen tussen warme en koele kant.','Un gradient thermique permet au serpent de choisir lui-même la bonne température en se déplaçant.','A thermal gradient lets the snake choose its own ideal temperature by moving around the enclosure.'),
(1,'tekst','Waarom heeft een korenslang een koele kant nodig in het terrarium?','Pourquoi un serpent des blés a-t-il besoin d''un côté frais dans le terrarium ?','Why does a corn snake need a cool side in its enclosure?','["Om te kunnen afkoelen en spijsvertering te regelen","Om te kunnen slapen","Omdat het decoratief is","Slangen hebben geen koele kant nodig"]'::jsonb,'["Pour pouvoir se refroidir et réguler la digestion","Pour pouvoir dormir","Pour la décoration","Les serpents n''ont pas besoin de côté frais"]'::jsonb,'["To cool down and help regulate digestion","So it can sleep","Just for decoration","Snakes don''t need a cool side"]'::jsonb,0,'Slangen zijn koudbloedig en gebruiken de omgeving om hun lichaamstemperatuur en spijsvertering te regelen.','Les serpents sont à sang froid et utilisent leur environnement pour réguler leur température et digestion.','Snakes are cold-blooded and use their environment to regulate body temperature and digestion.'),
(1,'tekst','Welke luchtvochtigheid is meestal geschikt voor een korenslang?','Quel taux d''humidité convient généralement à un serpent des blés ?','What humidity level is generally suitable for a corn snake?','["Ongeveer 40-50%","Ongeveer 90-100%","Ongeveer 5%","Luchtvochtigheid maakt niet uit"]'::jsonb,'["Environ 40-50%","Environ 90-100%","Environ 5%","L''humidité n''a pas d''importance"]'::jsonb,'["About 40-50%","About 90-100%","About 5%","Humidity doesn''t matter"]'::jsonb,0,'Te lage luchtvochtigheid kan problemen geven bij het vervellen, te hoge kan huidproblemen veroorzaken.','Une humidité trop basse peut poser problème lors de la mue, trop élevée peut causer des problèmes cutanés.','Too-low humidity can cause shedding problems, too-high humidity can cause skin issues.'),
(1,'tekst','Wat moet altijd aanwezig zijn in het terrarium van een korenslang?','Qu''est-ce qui doit toujours être présent dans le terrarium d''un serpent des blés ?','What should always be present in a corn snake''s enclosure?','["Een schuilplaats en vers water","Enkel een lamp","Een grote vijver","Niets, kaal terrarium is beter"]'::jsonb,'["Une cachette et de l''eau fraîche","Uniquement une lampe","Un grand bassin","Rien, un terrarium vide est préférable"]'::jsonb,'["A hiding spot and fresh water","Only a lamp","A large pond","Nothing, a bare enclosure is better"]'::jsonb,0,'Schuilplaatsen verminderen stress en vers water is essentieel, ook al drinken slangen niet vaak.','Les cachettes réduisent le stress et l''eau fraîche est essentielle, même si les serpents boivent peu souvent.','Hides reduce stress and fresh water is essential, even though snakes don''t drink very often.'),
(2,'tekst','Wat eten korenslangen normaal gezien?','Que mangent normalement les serpents des blés ?','What do corn snakes normally eat?','["Kleine knaagdieren zoals muizen","Enkel groenten","Insecten en fruit","Alleen melk"]'::jsonb,'["De petits rongeurs comme des souris","Uniquement des légumes","Des insectes et des fruits","Uniquement du lait"]'::jsonb,'["Small rodents like mice","Only vegetables","Insects and fruit","Only milk"]'::jsonb,0,'Korenslangen zijn vleeseters en jagen in het wild op knaagdieren en kleine vogels.','Les serpents des blés sont carnivores et chassent rongeurs et petits oiseaux dans la nature.','Corn snakes are carnivores that hunt rodents and small birds in the wild.'),
(2,'tekst','Hoe vaak moet een volwassen korenslang meestal gevoed worden?','À quelle fréquence un serpent des blés adulte doit-il généralement être nourri ?','How often does an adult corn snake usually need to be fed?','["Ongeveer om de 7-10 dagen","Elke dag","Eén keer per jaar","Nooit, ze eten zelfstandig"]'::jsonb,'["Environ tous les 7-10 jours","Chaque jour","Une fois par an","Jamais, ils se nourrissent seuls"]'::jsonb,'["About every 7-10 days","Every day","Once a year","Never, they feed themselves"]'::jsonb,0,'Volwassen korenslangen hebben een trage stofwisseling en hoeven niet vaak te eten.','Les serpents des blés adultes ont un métabolisme lent et n''ont pas besoin de manger souvent.','Adult corn snakes have a slow metabolism and don''t need to eat often.'),
(2,'tekst','Waarom is een vervelprobleem (stukjes oude huid blijven vastzitten) een teken van slechte verzorging?','Pourquoi un problème de mue (morceaux de peau qui restent collés) est-il un signe de mauvais soin ?','Why is a shedding problem (retained bits of old skin) a sign of poor care?','["Het wijst vaak op te lage luchtvochtigheid","Het is altijd normaal en onschadelijk","Het betekent dat de slang te veel eet","Het komt door te veel licht"]'::jsonb,'["Cela indique souvent une humidité trop basse","C''est toujours normal et sans danger","Cela signifie que le serpent mange trop","C''est dû à trop de lumière"]'::jsonb,'["It often points to too-low humidity","It is always normal and harmless","It means the snake eats too much","It is caused by too much light"]'::jsonb,0,'Onvoldoende vochtigheid tijdens de vervelling kan ervoor zorgen dat de huid niet volledig loslaat.','Une humidité insuffisante pendant la mue peut empêcher la peau de se détacher complètement.','Insufficient humidity during shedding can cause the skin to not fully release.'),
(2,'tekst','Wat is een teken van een gezonde korenslang?','Quel est un signe d''un serpent des blés en bonne santé ?','What is a sign of a healthy corn snake?','["Heldere ogen en regelmatige eetlust","Constant verstopt zonder te bewegen","Zichtbare mijten en wonden","Aanhoudend gewichtsverlies"]'::jsonb,'["Des yeux clairs et un appétit régulier","Toujours caché sans bouger","Des acariens et blessures visibles","Une perte de poids continue"]'::jsonb,'["Clear eyes and a regular appetite","Constantly hiding without moving","Visible mites and wounds","Continuous weight loss"]'::jsonb,0,'Gezonde slangen hebben heldere ogen, een gladde huid en een normaal eetpatroon.','Un serpent en bonne santé a les yeux clairs, une peau lisse et un appétit normal.','Healthy snakes have clear eyes, smooth skin and a normal appetite pattern.'),
(3,'tekst','Wanneer kun je een korenslang best niet vastnemen?','Quand vaut-il mieux ne pas manipuler un serpent des blés ?','When is it best not to handle a corn snake?','["Tijdens de vervelling","Elk moment is prima","Enkel bij zonsopgang","Nooit, handling maakt niet uit"]'::jsonb,'["Pendant la mue","N''importe quand, c''est très bien","Uniquement au lever du soleil","Jamais, la manipulation n''a pas d''importance"]'::jsonb,'["During shedding","Any time is fine","Only at sunrise","Never, handling doesn''t matter"]'::jsonb,0,'Tijdens de vervelling zien slangen slechter en kunnen ze extra gestrest of defensief reageren.','Pendant la mue, les serpents voient moins bien et peuvent réagir avec plus de stress ou de défense.','During shedding, snakes see less well and can react more defensively or stressed.'),
(3,'tekst','Hoe herken je stress bij een korenslang?','Comment reconnaît-on le stress chez un serpent des blés ?','How can you recognise stress in a corn snake?','["Sissen, aanhoudend verstoppen of weigeren te eten","Ze kwispelen met de staart van blijdschap","Ze slapen altijd 20 uur per dag, dat is stress","Stress is bij slangen niet zichtbaar"]'::jsonb,'["Siffler, se cacher constamment ou refuser de manger","Elles remuent la queue de joie","Elles dorment toujours 20h/jour, c''est du stress","Le stress n''est pas visible chez les serpents"]'::jsonb,'["Hissing, constant hiding, or refusing food","Wagging their tail happily","Sleeping 20 hours a day is stress","Stress isn''t visible in snakes"]'::jsonb,0,'Gedragsveranderingen zoals sissen, verstopgedrag of eetweigering kunnen wijzen op stress of onwelzijn.','Des changements de comportement comme siffler, se cacher ou refuser de manger peuvent indiquer du stress.','Behaviour changes like hissing, hiding, or refusing food can indicate stress or discomfort.'),
(3,'tekst','Hoe til je een korenslang best op?','Comment doit-on soulever un serpent des blés ?','How should you best pick up a corn snake?','["Rustig en met steun voor het volledige lichaam","Enkel bij de staart optillen","Snel vastgrijpen bij de kop","Nooit ondersteunen, laten hangen"]'::jsonb,'["Calmement, en soutenant tout le corps","En le soulevant uniquement par la queue","En l''attrapant rapidement par la tête","Sans jamais le soutenir, le laisser pendre"]'::jsonb,'["Calmly, supporting the whole body","Only lifting it by the tail","Grabbing it quickly by the head","Never supporting it, letting it dangle"]'::jsonb,0,'Het lichaam volledig ondersteunen voorkomt stress en verwondingen bij de slang.','Soutenir tout le corps évite le stress et les blessures chez le serpent.','Fully supporting the body prevents stress and injury to the snake.'),
(3,'tekst','Waarom is een deksel met slot belangrijk bij het terrarium van een korenslang?','Pourquoi un couvercle verrouillable est-il important pour le terrarium d''un serpent des blés ?','Why is a locking lid important for a corn snake''s enclosure?','["Korenslangen zijn sterke ontsnappingskunstenaars","Om licht buiten te houden","Om het terrarium te versieren","Slangen kunnen niet klimmen dus het is niet nodig"]'::jsonb,'["Les serpents des blés s''échappent très facilement","Pour bloquer la lumière","Pour décorer le terrarium","Les serpents ne grimpent pas donc ce n''est pas nécessaire"]'::jsonb,'["Corn snakes are skilled escape artists","To keep light out","To decorate the enclosure","Snakes can''t climb so it''s unnecessary"]'::jsonb,0,'Korenslangen kunnen door kleine openingen glippen en zijn bekend als echte ontsnappingsmeesters.','Les serpents des blés peuvent se faufiler par de petites ouvertures et sont connus pour s''échapper facilement.','Corn snakes can squeeze through small gaps and are well known for escaping enclosures.')
) AS v(module,vraag_type,nl,fr,en,onl,ofr,oen,ci,wnl,wfr,wen);

-- ============ BAARDAGAME ============
WITH a AS (
  INSERT INTO public.academies (diersoort_naam, diersoort_naam_fr, diersoort_naam_en, slug, badge_icon, vragen_per_test, slaag_grens, beschrijving, beschrijving_fr, beschrijving_en, categorie, prioriteit)
  VALUES ('Baardagame','Dragon barbu','Bearded Dragon','baardagame','baardagame',12,9,'De baardagame is een zonaanbiddende hagedis die sterke UVB-belichting en warmte nodig heeft om gezond te blijven.','Le dragon barbu est un lézard qui adore le soleil et a besoin d''un fort éclairage UVB et de chaleur pour rester en bonne santé.','The bearded dragon is a sun-loving lizard that needs strong UVB lighting and heat to stay healthy.','exoten',21)
  RETURNING id
)
INSERT INTO public.academy_vragen (academy_id, module, vraag_type, vraag_tekst, vraag_tekst_fr, vraag_tekst_en, opties, opties_fr, opties_en, correcte_optie_index, wist_je_dat, wist_je_dat_fr, wist_je_dat_en)
SELECT a.id, v.module, v.vraag_type, v.nl, v.fr, v.en, v.onl, v.ofr, v.oen, v.ci, v.wnl, v.wfr, v.wen
FROM a, (VALUES
(1,'tekst','Waarom heeft een baardagame UVB-licht nodig?','Pourquoi un dragon barbu a-t-il besoin de lumière UVB ?','Why does a bearded dragon need UVB light?','["Om vitamine D3 aan te maken voor calciumopname","Om beter te kunnen zien in het donker","Om een mooiere kleur te krijgen","UVB is niet nodig binnenshuis"]'::jsonb,'["Pour produire de la vitamine D3 et absorber le calcium","Pour mieux voir dans le noir","Pour avoir une plus belle couleur","L''UVB n''est pas nécessaire en intérieur"]'::jsonb,'["To produce vitamin D3 for calcium absorption","To see better in the dark","To get a nicer colour","UVB isn''t needed indoors"]'::jsonb,0,'Zonder UVB kan een baardagame geen vitamine D3 aanmaken en geen calcium goed opnemen, wat botproblemen veroorzaakt.','Sans UVB, un dragon barbu ne peut pas produire de vitamine D3 ni absorber le calcium, causant des problèmes osseux.','Without UVB, a bearded dragon cannot produce vitamin D3 or absorb calcium properly, causing bone disease.'),
(1,'tekst','Wat is een geschikte basking-temperatuur voor een baardagame?','Quelle est une température de zone de chauffe adaptée pour un dragon barbu ?','What is a suitable basking temperature for a bearded dragon?','["Ongeveer 38-42°C","Ongeveer 15°C","Ongeveer 60°C","Kamertemperatuur is voldoende"]'::jsonb,'["Environ 38-42°C","Environ 15°C","Environ 60°C","La température ambiante suffit"]'::jsonb,'["About 38-42°C","About 15°C","About 60°C","Room temperature is enough"]'::jsonb,0,'Baardagamen komen uit warme, droge streken van Australië en hebben hoge temperaturen nodig om te verteren.','Les dragons barbus viennent des régions chaudes et sèches d''Australie et ont besoin de hautes températures pour digérer.','Bearded dragons come from hot, dry Australian regions and need high temperatures to digest food.'),
(1,'tekst','Welke bodembedekking is aan te raden voor jonge baardagamen?','Quel substrat est recommandé pour les jeunes dragons barbus ?','What substrate is recommended for young bearded dragons?','["Een vast, niet-inslikbaar oppervlak zoals tegel of krant","Los zand dat makkelijk ingeslikt wordt","Fijne houtsnippers die stof veroorzaken","Geen bodembedekking is nodig noch aan te raden om te vermijden"]'::jsonb,'["Une surface solide et non ingérable comme du carrelage ou du papier","Du sable fin facilement ingéré","Des copeaux de bois fins qui font de la poussière","Aucun substrat n''est nécessaire"]'::jsonb,'["A solid, non-ingestible surface like tile or paper","Loose sand that is easily swallowed","Fine wood shavings that create dust","No substrate is needed at all"]'::jsonb,0,'Jonge baardagamen kunnen zand inslikken bij het jagen op voedsel, wat darmverstopping kan veroorzaken.','Les jeunes dragons barbus peuvent avaler du sable en chassant leur nourriture, ce qui peut causer une occlusion.','Young bearded dragons can swallow sand while hunting food, which can cause impaction.'),
(1,'tekst','Hoe groot moet het terrarium minstens zijn voor een volwassen baardagame?','Quelle taille minimale doit avoir le terrarium pour un dragon barbu adulte ?','How big should the enclosure be at minimum for an adult bearded dragon?','["Minstens 120x60x60 cm","Een kleine plastic bak van 30 cm volstaat","Ze hebben geen vast terrarium nodig","Een aquarium van 20 liter is genoeg"]'::jsonb,'["Au moins 120x60x60 cm","Un petit bac en plastique de 30 cm suffit","Ils n''ont pas besoin de terrarium fixe","Un aquarium de 20 litres suffit"]'::jsonb,'["At least 120x60x60 cm","A small 30cm plastic tub is enough","They don''t need a fixed enclosure","A 20-litre tank is enough"]'::jsonb,0,'Volwassen baardagamen worden vrij groot en hebben ruimte nodig voor een goede thermische gradiënt.','Les dragons barbus adultes deviennent assez grands et ont besoin d''espace pour un bon gradient thermique.','Adult bearded dragons grow quite large and need space for a proper thermal gradient.'),
(2,'tekst','Wat eet een baardagame in het wild en in gevangenschap?','Que mange un dragon barbu dans la nature et en captivité ?','What does a bearded dragon eat in the wild and in captivity?','["Een mix van insecten en groenten","Enkel vlees","Enkel fruit","Uitsluitend melkproducten"]'::jsonb,'["Un mélange d''insectes et de légumes","Uniquement de la viande","Uniquement des fruits","Uniquement des produits laitiers"]'::jsonb,'["A mix of insects and vegetables","Only meat","Only fruit","Only dairy products"]'::jsonb,0,'Baardagamen zijn omnivoren: jonge dieren eten meer insecten, volwassenen meer groenten.','Les dragons barbus sont omnivores : les jeunes mangent plus d''insectes, les adultes plus de légumes.','Bearded dragons are omnivores: young ones eat more insects, adults eat more vegetables.'),
(2,'tekst','Waarom moet voer bestrooid worden met calciumpoeder?','Pourquoi la nourriture doit-elle être saupoudrée de poudre de calcium ?','Why should food be dusted with calcium powder?','["Om metabole botziekte te voorkomen","Om het voer lekkerder te maken","Het is niet nodig als er UVB is","Om de kleur van het voer te verbeteren"]'::jsonb,'["Pour prévenir la maladie osseuse métabolique","Pour rendre la nourriture plus savoureuse","Ce n''est pas nécessaire s''il y a de l''UVB","Pour améliorer la couleur de la nourriture"]'::jsonb,'["To prevent metabolic bone disease","To make the food taste better","It''s not needed if there''s UVB","To improve the colour of the food"]'::jsonb,0,'Extra calcium is nodig naast UVB om voldoende opname te garanderen en botproblemen te voorkomen.','Un apport supplémentaire de calcium est nécessaire en plus de l''UVB pour garantir une bonne absorption.','Extra calcium is needed alongside UVB to ensure proper absorption and prevent bone problems.'),
(2,'tekst','Wat kan een teken zijn van metabole botziekte bij een baardagame?','Quel peut être un signe de maladie osseuse métabolique chez un dragon barbu ?','What can be a sign of metabolic bone disease in a bearded dragon?','["Zwakke of gebogen ledematen","Een extra lange staart","Een groter dan normaal hongergevoel","Snellere groei dan normaal"]'::jsonb,'["Des membres faibles ou tordus","Une queue anormalement longue","Un appétit plus grand que la normale","Une croissance plus rapide que la normale"]'::jsonb,'["Weak or bent limbs","An unusually long tail","A bigger-than-normal appetite","Faster growth than normal"]'::jsonb,0,'Een tekort aan calcium en UVB kan leiden tot zachte, misvormde botten en zwakte.','Un manque de calcium et d''UVB peut entraîner des os mous, déformés et une faiblesse générale.','A lack of calcium and UVB can lead to soft, deformed bones and weakness.'),
(2,'tekst','Hoe vaak moet je vers water en voer verversen voor een baardagame?','À quelle fréquence faut-il renouveler l''eau et la nourriture fraîches d''un dragon barbu ?','How often should fresh water and food be refreshed for a bearded dragon?','["Dagelijks","Eén keer per maand","Enkel bij ziekte","Nooit nodig, ze drinken niet"]'::jsonb,'["Quotidiennement","Une fois par mois","Uniquement en cas de maladie","Jamais nécessaire, ils ne boivent pas"]'::jsonb,'["Daily","Once a month","Only when sick","Never needed, they don''t drink"]'::jsonb,0,'Dagelijks vers water en voer voorkomt bacteriegroei en houdt de baardagame gezond.','De l''eau et de la nourriture fraîches chaque jour préviennent la prolifération bactérienne.','Fresh water and food daily prevents bacterial growth and keeps the dragon healthy.'),
(3,'tekst','Wat betekent het als een baardagame zwaait met een voorpoot?','Que signifie le fait qu''un dragon barbu agite une patte avant ?','What does it mean when a bearded dragon waves a front leg?','["Een onderdanig of sociaal signaal","Een teken van agressie","Ze proberen te vliegen","Het betekent dat ze honger hebben"]'::jsonb,'["Un signal de soumission ou social","Un signe d''agressivité","Elles essaient de voler","Cela signifie qu''elles ont faim"]'::jsonb,'["A submissive or social signal","A sign of aggression","They are trying to fly","It means they are hungry"]'::jsonb,0,'Armzwaaien is een natuurlijk sociaal gedrag waarmee baardagamen communiceren zonder confrontatie.','Le fait d''agiter le bras est un comportement social naturel utilisé pour communiquer sans confrontation.','Arm-waving is a natural social behaviour bearded dragons use to communicate without confrontation.'),
(3,'tekst','Wat betekent een zwarte baard bij een baardagame meestal?','Que signifie généralement une barbe noire chez un dragon barbu ?','What does a black beard usually mean in a bearded dragon?','["Stress, dreiging of opwinding","Dat het dier honger heeft","Dat het dier gaat vervellen","Dat het dier ziek is van kou"]'::jsonb,'["Du stress, une menace ou de l''excitation","Que l''animal a faim","Que l''animal va muer","Que l''animal est malade à cause du froid"]'::jsonb,'["Stress, a threat display, or excitement","That it is hungry","That it is about to shed","That it is sick from cold"]'::jsonb,0,'Het opzwellen en donker kleuren van de baard is een waarschuwings- of stresssignaal.','Le gonflement et l''assombrissement de la barbe est un signal d''avertissement ou de stress.','Puffing up and darkening the beard is a warning or stress signal.'),
(3,'tekst','Hoe til je een baardagame best correct op?','Comment doit-on correctement soulever un dragon barbu ?','How should you correctly pick up a bearded dragon?','["Met beide handen het volledige lichaam ondersteunend","Bij de staart optillen","Snel van bovenaf grijpen","Nooit optillen, enkel laten lopen"]'::jsonb,'["Avec les deux mains en soutenant tout le corps","En le soulevant par la queue","En l''attrapant rapidement par le dessus","Ne jamais le soulever, juste le laisser marcher"]'::jsonb,'["With both hands, supporting the whole body","By lifting it by the tail","By grabbing quickly from above","Never lift it, just let it walk"]'::jsonb,0,'Het lichaam ondersteunen voorkomt letsel en stress, want plotse bewegingen van boven kunnen als roofdiergedrag overkomen.','Soutenir le corps évite les blessures et le stress, car un geste brusque par le dessus peut ressembler à une attaque.','Supporting the body prevents injury and stress, as sudden overhead movement can resemble predator behaviour.'),
(3,'tekst','Waarom moet je jonge kinderen begeleiden bij contact met een baardagame op de kinderboerderij?','Pourquoi faut-il accompagner les jeunes enfants lors du contact avec un dragon barbu à la ferme pédagogique ?','Why should young children be supervised when in contact with a bearded dragon at a city farm?','["Om stress bij het dier en hygiëneproblemen te vermijden","Omdat baardagamen erg gevaarlijk gif hebben","Omdat ze snel bijten zonder reden","Begeleiding is niet nodig, ze zijn nooit stressgevoelig"]'::jsonb,'["Pour éviter le stress de l''animal et les problèmes d''hygiène","Parce que les dragons barbus ont un venin dangereux","Parce qu''ils mordent souvent sans raison","Aucun accompagnement n''est nécessaire"]'::jsonb,'["To avoid stressing the animal and hygiene issues","Because bearded dragons have dangerous venom","Because they often bite without reason","Supervision isn''t needed, they never get stressed"]'::jsonb,0,'Ruw hanteren stresst het dier en reptielen kunnen salmonella dragen, dus handen wassen na contact is belangrijk.','Une manipulation brusque stresse l''animal et les reptiles peuvent porter la salmonelle, se laver les mains est important.','Rough handling stresses the animal and reptiles can carry salmonella, so washing hands after contact matters.')
) AS v(module,vraag_type,nl,fr,en,onl,ofr,oen,ci,wnl,wfr,wen);

-- ============ SCHILDPAD ============
WITH a AS (
  INSERT INTO public.academies (diersoort_naam, diersoort_naam_fr, diersoort_naam_en, slug, badge_icon, vragen_per_test, slaag_grens, beschrijving, beschrijving_fr, beschrijving_en, categorie, prioriteit)
  VALUES ('Schildpad','Tortue','Tortoise','schildpad','schildpad',12,9,'Schildpadden zijn langlevende reptielen die specifieke warmte, UVB en verzorging nodig hebben om gezond oud te worden.','Les tortues sont des reptiles à longue durée de vie qui ont besoin de chaleur, d''UVB et de soins spécifiques.','Tortoises are long-lived reptiles that need specific heat, UVB and care to stay healthy for many years.','exoten',22)
  RETURNING id
)
INSERT INTO public.academy_vragen (academy_id, module, vraag_type, vraag_tekst, vraag_tekst_fr, vraag_tekst_en, opties, opties_fr, opties_en, correcte_optie_index, wist_je_dat, wist_je_dat_fr, wist_je_dat_en)
SELECT a.id, v.module, v.vraag_type, v.nl, v.fr, v.en, v.onl, v.ofr, v.oen, v.ci, v.wnl, v.wfr, v.wen
FROM a, (VALUES
(1,'tekst','Waarom hebben landschildpadden een groot buitenverblijf nodig als het weer het toelaat?','Pourquoi les tortues terrestres ont-elles besoin d''un grand enclos extérieur quand le temps le permet ?','Why do tortoises need a large outdoor enclosure when weather allows?','["Voor natuurlijk zonlicht, beweging en gevarieerd gedrag","Om te kunnen zwemmen in diep water","Omdat ze binnen niet kunnen ademen","Ruimte is niet belangrijk voor schildpadden"]'::jsonb,'["Pour la lumière naturelle, le mouvement et un comportement varié","Pour pouvoir nager en eau profonde","Parce qu''elles ne peuvent pas respirer à l''intérieur","L''espace n''est pas important pour les tortues"]'::jsonb,'["For natural sunlight, exercise and varied behaviour","To be able to swim in deep water","Because they can''t breathe indoors","Space isn''t important for tortoises"]'::jsonb,0,'Natuurlijk zonlicht levert UVB dat essentieel is voor de aanmaak van vitamine D3.','La lumière naturelle du soleil fournit des UVB essentiels à la production de vitamine D3.','Natural sunlight provides UVB that is essential for vitamin D3 production.'),
(1,'tekst','Wat hebben waterschildpadden nodig naast water om in te zwemmen?','De quoi les tortues aquatiques ont-elles besoin en plus de l''eau pour nager ?','What do aquatic turtles need besides water to swim in?','["Een droog eiland of basking-plek om te zonnen","Enkel meer water, niets anders","Volledige duisternis","Een tweede aquarium zonder water"]'::jsonb,'["Une île sèche ou zone de bain de soleil","Simplement plus d''eau, rien d''autre","L''obscurité totale","Un deuxième aquarium sans eau"]'::jsonb,'["A dry basking island or spot to sunbathe","Just more water, nothing else","Complete darkness","A second tank without water"]'::jsonb,0,'Waterschildpadden moeten volledig kunnen opdrogen op een basking-plek om schimmel- en huidproblemen te voorkomen.','Les tortues aquatiques doivent pouvoir sécher complètement sur une zone de bain pour éviter les mycoses.','Aquatic turtles must be able to fully dry off on a basking spot to prevent fungal and skin problems.'),
(1,'tekst','Welke rol speelt UVB-belichting voor schildpadden?','Quel est le rôle de l''éclairage UVB pour les tortues ?','What role does UVB lighting play for tortoises?','["Het helpt vitamine D3 en een gezond schild vormen","Het dient enkel om het terrarium te verlichten","UVB is schadelijk voor schildpadden","Schildpadden hebben geen licht nodig"]'::jsonb,'["Elle aide à produire la vitamine D3 et une carapace saine","Elle sert uniquement à éclairer le terrarium","L''UVB est nocif pour les tortues","Les tortues n''ont pas besoin de lumière"]'::jsonb,'["It helps produce vitamin D3 and a healthy shell","It''s just to light up the enclosure","UVB is harmful to tortoises","Tortoises don''t need light"]'::jsonb,0,'Zonder UVB kan het schild zwak en misvormd groeien door gebrekkige calciumopname.','Sans UVB, la carapace peut devenir faible et déformée à cause d''une mauvaise absorption du calcium.','Without UVB, the shell can grow weak and deformed due to poor calcium absorption.'),
(1,'tekst','Wat is belangrijk bij het inrichten van een schuilplaats voor een schildpad?','Qu''est-ce qui est important dans l''aménagement d''une cachette pour une tortue ?','What is important when setting up a hiding spot for a tortoise?','["Ze moet donker, veilig en op maat van het dier zijn","Ze moet doorzichtig zijn zodat bezoekers alles zien","Schuilplaatsen zijn niet nodig","Ze moet altijd verlicht zijn"]'::jsonb,'["Elle doit être sombre, sûre et adaptée à la taille de l''animal","Elle doit être transparente pour que les visiteurs voient tout","Les cachettes ne sont pas nécessaires","Elle doit toujours être éclairée"]'::jsonb,'["It should be dark, safe and sized for the animal","It should be transparent so visitors can see everything","Hiding spots aren''t necessary","It should always be lit"]'::jsonb,0,'Een veilige schuilplaats vermindert stress en geeft de schildpad controle over haar omgeving.','Une cachette sûre réduit le stress et donne à la tortue un contrôle sur son environnement.','A safe hiding spot reduces stress and gives the tortoise control over its environment.'),
(2,'tekst','Wat eten de meeste landschildpadden hoofdzakelijk?','Que mangent principalement la plupart des tortues terrestres ?','What do most tortoises mainly eat?','["Vezelrijke groenten en onkruid","Vlees en vis","Enkel fruit","Kattenvoeding"]'::jsonb,'["Des légumes fibreux et des herbes sauvages","De la viande et du poisson","Uniquement des fruits","De la nourriture pour chat"]'::jsonb,'["Fibre-rich greens and weeds","Meat and fish","Only fruit","Cat food"]'::jsonb,0,'De meeste landschildpadden zijn herbivoren en hebben veel vezels nodig voor een gezonde spijsvertering.','La plupart des tortues terrestres sont herbivores et ont besoin de fibres pour une bonne digestion.','Most tortoises are herbivores and need lots of fibre for healthy digestion.'),
(2,'tekst','Waarom is te veel fruit slecht voor een landschildpad?','Pourquoi trop de fruits est-il mauvais pour une tortue terrestre ?','Why is too much fruit bad for a tortoise?','["Te veel suiker kan de darmflora en gezondheid verstoren","Fruit is giftig voor schildpadden","Schildpadden kunnen fruit niet ruiken","Fruit veroorzaakt schildgroei"]'::jsonb,'["Trop de sucre peut perturber la flore intestinale et la santé","Les fruits sont toxiques pour les tortues","Les tortues ne peuvent pas sentir les fruits","Les fruits provoquent la croissance de la carapace"]'::jsonb,'["Too much sugar can disrupt gut flora and health","Fruit is toxic to tortoises","Tortoises can''t smell fruit","Fruit causes shell growth"]'::jsonb,0,'Overmatige suiker uit fruit kan leiden tot spijsverteringsproblemen en parasietenoverlast.','Un excès de sucre provenant des fruits peut causer des problèmes digestifs et favoriser les parasites.','Excess sugar from fruit can lead to digestive issues and parasite problems.'),
(2,'tekst','Wat is een teken van een ongezond schild bij een schildpad?','Quel est un signe d''une carapace en mauvaise santé chez une tortue ?','What is a sign of an unhealthy shell in a tortoise?','["Zachte plekken of onregelmatige groei (piramidevorming)","Een glanzend, glad oppervlak","Een gelijkmatige lichte kleur","Normale groeiringen"]'::jsonb,'["Des zones molles ou une croissance irrégulière (pyramidage)","Une surface brillante et lisse","Une couleur claire uniforme","Des anneaux de croissance normaux"]'::jsonb,'["Soft patches or irregular growth (pyramiding)","A shiny, smooth surface","An even light colour","Normal growth rings"]'::jsonb,0,'Piramidevorming en zachte plekken wijzen vaak op een tekort aan calcium, UVB of een verkeerd dieet.','Le pyramidage et les zones molles indiquent souvent un manque de calcium, d''UVB ou une alimentation inadaptée.','Pyramiding and soft patches often point to a lack of calcium, UVB, or an incorrect diet.'),
(2,'tekst','Hoe vaak moet vers water beschikbaar zijn voor een schildpad?','À quelle fréquence de l''eau fraîche doit-elle être disponible pour une tortue ?','How often should fresh water be available for a tortoise?','["Altijd, dagelijks ververst","Enkel één keer per week","Alleen in de zomer","Schildpadden hebben geen water nodig"]'::jsonb,'["Toujours, renouvelée quotidiennement","Seulement une fois par semaine","Uniquement en été","Les tortues n''ont pas besoin d''eau"]'::jsonb,'["Always, refreshed daily","Only once a week","Only in summer","Tortoises don''t need water"]'::jsonb,0,'Schildpadden drinken en weken regelmatig in water, wat belangrijk is voor hydratatie en spijsvertering.','Les tortues boivent et se trempent régulièrement dans l''eau, important pour l''hydratation et la digestion.','Tortoises drink and soak in water regularly, which is important for hydration and digestion.'),
(3,'tekst','Wat betekent het als een schildpad zich volledig terugtrekt in haar schild bij aanraking?','Que signifie le fait qu''une tortue se rétracte complètement dans sa carapace au contact ?','What does it mean when a tortoise fully retracts into its shell when touched?','["Ze voelt zich bedreigd of gestrest","Ze wil spelen","Ze heeft honger","Het betekent niets speciaals"]'::jsonb,'["Elle se sent menacée ou stressée","Elle veut jouer","Elle a faim","Cela ne signifie rien de particulier"]'::jsonb,'["It feels threatened or stressed","It wants to play","It is hungry","It means nothing in particular"]'::jsonb,0,'Terugtrekken in het schild is een natuurlijk verdedigingsmechanisme tegen gevaar of stress.','Se rétracter dans la carapace est un mécanisme de défense naturel contre le danger ou le stress.','Retracting into the shell is a natural defence mechanism against danger or stress.'),
(3,'tekst','Waarom moet je een schildpad nooit op haar rug leggen of laten liggen?','Pourquoi ne faut-il jamais poser ou laisser une tortue sur le dos ?','Why should you never leave a tortoise on its back?','["Dit kan ademhalingsproblemen en zware stress veroorzaken","Schildpadden vinden dit net leuk","Het heeft geen enkel effect op hen","Ze kunnen zichzelf altijd makkelijk omdraaien"]'::jsonb,'["Cela peut causer des problèmes respiratoires et un stress important","Les tortues aiment bien ça","Cela n''a aucun effet sur elles","Elles peuvent toujours se retourner facilement"]'::jsonb,'["It can cause breathing difficulty and severe stress","Tortoises actually enjoy it","It has no effect on them at all","They can always easily flip themselves back"]'::jsonb,0,'Op de rug liggen kan de organen onder druk zetten en veroorzaakt hevige paniek bij het dier.','Être sur le dos peut comprimer les organes et provoquer une grande panique chez l''animal.','Lying on its back can put pressure on organs and cause severe panic in the animal.'),
(3,'tekst','Hoe til je een schildpad best correct op?','Comment doit-on correctement soulever une tortue ?','How should you correctly pick up a tortoise?','["Met beide handen, laag bij de grond, schild goed ondersteund","Bij één poot optillen","Snel en hoog in de lucht gooien","Aan de staart optillen"]'::jsonb,'["Avec les deux mains, près du sol, carapace bien soutenue","En la soulevant par une seule patte","En la lançant rapidement en l''air","En la soulevant par la queue"]'::jsonb,'["With both hands, low to the ground, shell well supported","By lifting it by one leg","By tossing it quickly in the air","By lifting it by the tail"]'::jsonb,0,'Laag bij de grond optillen vermindert het risico op letsel bij een eventuele val.','Soulever près du sol réduit le risque de blessure en cas de chute.','Lifting low to the ground reduces the risk of injury from a possible fall.'),
(3,'tekst','Waarom moeten kinderen op de kinderboerderij hun handen wassen na contact met een schildpad?','Pourquoi les enfants doivent-ils se laver les mains après avoir touché une tortue à la ferme pédagogique ?','Why should children wash their hands after touching a tortoise at the city farm?','["Om het risico op salmonella-overdracht te verminderen","Omdat schildpadden vies ruiken","Omdat het schild giftig is","Het is niet nodig, schildpadden zijn steriel"]'::jsonb,'["Pour réduire le risque de transmission de la salmonelle","Parce que les tortues sentent mauvais","Parce que la carapace est toxique","Ce n''est pas nécessaire, les tortues sont stériles"]'::jsonb,'["To reduce the risk of salmonella transmission","Because tortoises smell bad","Because the shell is toxic","It''s not needed, tortoises are sterile"]'::jsonb,0,'Reptielen kunnen salmonellabacteriën dragen zonder zelf ziek te zijn, dus handen wassen is een belangrijke hygiëneregel.','Les reptiles peuvent porter la salmonelle sans être malades eux-mêmes, se laver les mains est une règle d''hygiène importante.','Reptiles can carry salmonella bacteria without being sick themselves, so handwashing is an important hygiene rule.')
) AS v(module,vraag_type,nl,fr,en,onl,ofr,oen,ci,wnl,wfr,wen);

-- ============ AXOLOTL ============
WITH a AS (
  INSERT INTO public.academies (diersoort_naam, diersoort_naam_fr, diersoort_naam_en, slug, badge_icon, vragen_per_test, slaag_grens, beschrijving, beschrijving_fr, beschrijving_en, categorie, prioriteit)
  VALUES ('Axolotl','Axolotl','Axolotl','axolotl','axolotl',12,9,'De axolotl is een unieke Mexicaanse watersalamander die koel, zuurstofrijk water en rustige verzorging nodig heeft.','L''axolotl est une salamandre aquatique mexicaine unique qui a besoin d''eau fraîche, oxygénée et de soins calmes.','The axolotl is a unique Mexican salamander that needs cool, oxygen-rich water and gentle care.','exoten',23)
  RETURNING id
)
INSERT INTO public.academy_vragen (academy_id, module, vraag_type, vraag_tekst, vraag_tekst_fr, vraag_tekst_en, opties, opties_fr, opties_en, correcte_optie_index, wist_je_dat, wist_je_dat_fr, wist_je_dat_en)
SELECT a.id, v.module, v.vraag_type, v.nl, v.fr, v.en, v.onl, v.ofr, v.oen, v.ci, v.wnl, v.wfr, v.wen
FROM a, (VALUES
(1,'tekst','Welke watertemperatuur is ideaal voor een axolotl?','Quelle température de l''eau est idéale pour un axolotl ?','What water temperature is ideal for an axolotl?','["Ongeveer 16-18°C","Ongeveer 28-30°C","Ongeveer 5°C","Temperatuur maakt niet uit"]'::jsonb,'["Environ 16-18°C","Environ 28-30°C","Environ 5°C","La température n''a pas d''importance"]'::jsonb,'["About 16-18°C","About 28-30°C","About 5°C","Temperature doesn''t matter"]'::jsonb,0,'Axolotls komen uit koele bergmeren in Mexico en lijden onder warm water, dat hun stofwisseling en immuunsysteem verstoort.','Les axolotls viennent de lacs de montagne froids au Mexique et souffrent dans une eau chaude.','Axolotls come from cool mountain lakes in Mexico and suffer in warm water, which stresses their metabolism.'),
(1,'tekst','Waarom is een filter met zachte, langzame stroming belangrijk in een axolotlaquarium?','Pourquoi un filtre à courant doux et lent est-il important dans un aquarium à axolotl ?','Why is a filter with a gentle, slow flow important in an axolotl tank?','["Sterke stroming stresst axolotls en bemoeilijkt zwemmen","Axolotls houden juist van sterke stroming","Filters zijn niet nodig voor axolotls","Stroming heeft geen effect op axolotls"]'::jsonb,'["Un fort courant stresse les axolotls et gêne leur nage","Les axolotls adorent au contraire un fort courant","Les filtres ne sont pas nécessaires pour les axolotls","Le courant n''a aucun effet sur les axolotls"]'::jsonb,'["Strong flow stresses axolotls and makes swimming difficult","Axolotls actually love strong currents","Filters aren''t needed for axolotls","Flow has no effect on axolotls"]'::jsonb,0,'Axolotls leven van nature in rustig water en hebben moeite met sterke stromingen die energie kosten.','Les axolotls vivent naturellement en eau calme et ont du mal avec les forts courants.','Axolotls naturally live in calm water and struggle with strong currents that cost them energy.'),
(1,'tekst','Wat is een geschikte bodembedekking voor een axolotlaquarium?','Quel substrat convient pour un aquarium à axolotl ?','What is a suitable substrate for an axolotl tank?','["Fijn zand of een kale bodem","Grof grind dat ingeslikt kan worden","Scherpe stenen","Er is geen bodembedekking nodig noch geschikt"]'::jsonb,'["Du sable fin ou un fond nu","Du gravier grossier qui peut être avalé","Des pierres tranchantes","Aucun substrat n''est nécessaire ni adapté"]'::jsonb,'["Fine sand or a bare bottom","Coarse gravel that can be swallowed","Sharp stones","No substrate is needed or suitable"]'::jsonb,0,'Grof grind kan door axolotls worden ingeslikd tijdens het jagen en darmverstopping veroorzaken.','Le gravier grossier peut être avalé par les axolotls en chassant et provoquer une occlusion intestinale.','Coarse gravel can be swallowed by axolotls while hunting and cause intestinal blockage.'),
(1,'tekst','Waarom hebben axolotls geen UVB-lamp of basking-plek nodig, in tegenstelling tot veel reptielen?','Pourquoi les axolotls n''ont-ils pas besoin de lampe UVB ni de zone de bain, contrairement à beaucoup de reptiles ?','Why don''t axolotls need a UVB lamp or basking spot, unlike many reptiles?','["Ze zijn volledig aquatisch en verlaten het water nooit","Ze zijn eigenlijk reptielen die zonlicht nodig hebben","UVB is toch nodig, dit is een foute veronderstelling","Axolotls hebben net een sterkere UVB nodig dan reptielen"]'::jsonb,'["Ils sont entièrement aquatiques et ne quittent jamais l''eau","Ce sont en fait des reptiles qui ont besoin de soleil","L''UVB est quand même nécessaire","Les axolotls ont besoin d''un UVB encore plus fort que les reptiles"]'::jsonb,'["They are fully aquatic and never leave the water","They are actually reptiles that need sunlight","UVB is needed after all, this is a wrong assumption","Axolotls need even stronger UVB than reptiles"]'::jsonb,0,'Axolotls zijn amfibieën die hun hele leven in het water blijven en dus geen basking-gedrag vertonen zoals reptielen.','Les axolotls sont des amphibiens qui restent toute leur vie dans l''eau et n''ont donc pas besoin de bain de soleil.','Axolotls are amphibians that stay in water their whole life and therefore don''t bask like reptiles.'),
(2,'tekst','Wat eten axolotls voornamelijk?','Que mangent principalement les axolotls ?','What do axolotls mainly eat?','["Wormen, kleine kreeftjes en speciale korrels","Groenten en fruit","Enkel plantaardig materiaal","Brood en graanproducten"]'::jsonb,'["Des vers, petites crevettes et granulés spécifiques","Des légumes et des fruits","Uniquement des matières végétales","Du pain et des céréales"]'::jsonb,'["Worms, small crustaceans and specialised pellets","Vegetables and fruit","Only plant material","Bread and grain products"]'::jsonb,0,'Axolotls zijn vleeseters en jagen met hun uitstekende reukzin naar kleine waterdieren.','Les axolotls sont carnivores et chassent de petits animaux aquatiques grâce à leur excellent odorat.','Axolotls are carnivores and hunt small aquatic prey using their excellent sense of smell.'),
(2,'tekst','Waarom is een goede waterkwaliteit cruciaal voor de gezondheid van een axolotl?','Pourquoi une bonne qualité de l''eau est-elle cruciale pour la santé d''un axolotl ?','Why is good water quality crucial for an axolotl''s health?','["Axolotls ademen via kieuwen en huid, gevoelig voor vervuild water","Axolotls ademen enkel lucht dus water speelt geen rol","Waterkwaliteit heeft geen invloed op amfibieën","Axolotls filteren zelf hun water perfect"]'::jsonb,'["Les axolotls respirent par branchies et peau, sensibles à l''eau polluée","Les axolotls ne respirent que de l''air donc l''eau importe peu","La qualité de l''eau n''a aucun effet sur les amphibiens","Les axolotls filtrent parfaitement leur eau eux-mêmes"]'::jsonb,'["Axolotls breathe through gills and skin, sensitive to dirty water","Axolotls only breathe air so water quality doesn''t matter","Water quality has no effect on amphibians","Axolotls filter their own water perfectly"]'::jsonb,0,'Vervuild water met ammoniak of nitriet kan via de gevoelige huid en kieuwen snel schade toebrengen.','Une eau polluée par l''ammoniac ou les nitrites peut rapidement nuire via la peau sensible et les branchies.','Polluted water with ammonia or nitrite can quickly cause harm via the sensitive skin and gills.'),
(2,'tekst','Wat is een teken van stress of ziekte bij een axolotl?','Quel est un signe de stress ou de maladie chez un axolotl ?','What is a sign of stress or illness in an axolotl?','["Gekrompen of beschadigde kieuwen","Grote, pluizige kieuwen","Actief zwemmen na het voeren","Rustig op de bodem liggen"]'::jsonb,'["Des branchies rétrécies ou abîmées","De grandes branchies touffues","Nager activement après avoir mangé","Se reposer calmement au fond"]'::jsonb,'["Shrunken or damaged gills","Large, fluffy gills","Swimming actively after feeding","Resting calmly on the bottom"]'::jsonb,0,'Gezonde kieuwen zijn vol en pluizig; gekrompen kieuwen wijzen vaak op slechte waterkwaliteit of stress.','Des branchies saines sont pleines et touffues ; des branchies rétrécies indiquent souvent une mauvaise qualité de l''eau.','Healthy gills are full and fluffy; shrunken gills often indicate poor water quality or stress.'),
(2,'tekst','Hoe vaak moet je een volwassen axolotl voeren?','À quelle fréquence faut-il nourrir un axolotl adulte ?','How often should you feed an adult axolotl?','["Ongeveer om de 2-3 dagen","Meerdere keren per dag","Eén keer per maand","Nooit, ze eten van nature niets"]'::jsonb,'["Environ tous les 2-3 jours","Plusieurs fois par jour","Une fois par mois","Jamais, ils ne mangent naturellement rien"]'::jsonb,'["About every 2-3 days","Several times a day","Once a month","Never, they naturally eat nothing"]'::jsonb,0,'Te vaak voeren kan de waterkwaliteit snel verslechteren en obesitas veroorzaken bij axolotls.','Nourrir trop souvent peut rapidement dégrader la qualité de l''eau et causer l''obésité chez les axolotls.','Feeding too often can quickly worsen water quality and cause obesity in axolotls.'),
(3,'tekst','Waarom moet je een axolotl zo weinig mogelijk uit het water hanteren?','Pourquoi faut-il manipuler un axolotl le moins possible hors de l''eau ?','Why should you handle an axolotl out of water as little as possible?','["Hun huid is zeer gevoelig en droogt snel uit","Axolotls kunnen makkelijk een tijdje op het droge leven","Handling buiten water versterkt hun kieuwen","Het heeft geen enkel effect op hun welzijn"]'::jsonb,'["Leur peau est très sensible et sèche rapidement","Les axolotls peuvent facilement vivre un moment hors de l''eau","La manipulation hors de l''eau renforce leurs branchies","Cela n''a aucun effet sur leur bien-être"]'::jsonb,'["Their skin is very sensitive and dries out quickly","Axolotls can easily live out of water for a while","Handling out of water strengthens their gills","It has no effect on their wellbeing at all"]'::jsonb,0,'De huid van axolotls heeft geen beschermende schubben en is erg gevoelig voor uitdroging en beschadiging.','La peau des axolotls n''a pas d''écailles protectrices et est très sensible au dessèchement et aux blessures.','Axolotl skin has no protective scales and is very sensitive to drying out and injury.'),
(3,'tekst','Wat moet je vermijden bij het optillen van een axolotl indien echt nodig?','Que faut-il éviter en soulevant un axolotl si c''est vraiment nécessaire ?','What should you avoid when lifting an axolotl if truly necessary?','["Het vastpakken met droge handen of een net met scherpe randen","Het gebruik van een natte kom of bakje","Het ondersteunen van het volledige lichaam","Het kort uit het water halen"]'::jsonb,'["Le saisir avec des mains sèches ou un filet aux bords tranchants","Utiliser un bol ou récipient humide","Soutenir tout le corps","Le sortir brièvement de l''eau"]'::jsonb,'["Grabbing it with dry hands or a net with sharp edges","Using a wet bowl or container","Supporting the whole body","Briefly taking it out of the water"]'::jsonb,0,'Droge handen en netten kunnen de gevoelige huid en kieuwen van een axolotl beschadigen.','Des mains sèches et des filets peuvent endommager la peau sensible et les branchies d''un axolotl.','Dry hands and nets can damage an axolotl''s sensitive skin and gills.'),
(3,'tekst','Wat betekent het als een axolotl zijn kieuwen platlegt tegen het lichaam?','Que signifie le fait qu''un axolotl plaque ses branchies contre son corps ?','What does it mean when an axolotl flattens its gills against its body?','["Mogelijk stress of slechte waterkwaliteit","Het dier is aan het spelen","Het is een teken van honger","Het betekent dat het dier gaat groeien"]'::jsonb,'["Un possible stress ou une mauvaise qualité de l''eau","L''animal est en train de jouer","C''est un signe de faim","Cela signifie que l''animal va grandir"]'::jsonb,'["Possible stress or poor water quality","The animal is playing","It is a sign of hunger","It means the animal is about to grow"]'::jsonb,0,'Platliggende kieuwen kunnen wijzen op ongemak, stress of een probleem met de waterparameters.','Des branchies aplaties peuvent indiquer un inconfort, du stress ou un problème de paramètres de l''eau.','Flattened gills can indicate discomfort, stress, or a problem with water parameters.'),
(3,'tekst','Waarom is rustig, minimaal contact belangrijk voor axolotls op een kinderboerderij?','Pourquoi un contact calme et minimal est-il important pour les axolotls dans une ferme pédagogique ?','Why is calm, minimal contact important for axolotls at a city farm?','["Ze zijn gevoelige dieren die snel gestrest raken door aanraking","Axolotls genieten juist van veel fysiek contact","Contact heeft geen invloed op axolotls","Ze moeten net vaak gestreeld worden voor hun gezondheid"]'::jsonb,'["Ce sont des animaux sensibles qui stressent vite au contact","Les axolotls adorent au contraire beaucoup de contact physique","Le contact n''a aucune influence sur les axolotls","Ils doivent au contraire être souvent caressés pour leur santé"]'::jsonb,'["They are sensitive animals that stress easily from touch","Axolotls actually enjoy lots of physical contact","Contact has no effect on axolotls at all","They actually need frequent petting for their health"]'::jsonb,0,'Axolotls zijn niet gewend aan handling en fysiek contact kan hun kwetsbare huid en welzijn schaden.','Les axolotls ne sont pas habitués à être manipulés et le contact physique peut nuire à leur peau fragile.','Axolotls aren''t used to handling, and physical contact can harm their fragile skin and wellbeing.')
) AS v(module,vraag_type,nl,fr,en,onl,ofr,oen,ci,wnl,wfr,wen);
